package dev.gyeopdam.embeddedtor;
import java.io.IOException;
import java.util.*;
import java.util.concurrent.Executor;
import org.json.JSONObject;
import org.junit.Test;
import static org.junit.Assert.*;
public class DeviceRecoveryCoordinatorTest {
 static final String O="http://"+"a".repeat(56)+".onion", A="demo-account-a", D="demo-device-old", OLD="gd_acct_"+"A".repeat(43), NEW="gd_acct_"+"B".repeat(42)+"A", ID="demo-recovery-a";
 static AppSessionStore.Session session(String account){return new AppSessionStore.Session(O,account,"","","","gd_sess_"+"A".repeat(43));}
 static PendingDeviceRecoveryStore.Pending pending(boolean confirmed){return new PendingDeviceRecoveryStore.Pending(O,A,D,ID,OLD,NEW,confirmed);}
 static class Queue implements Executor {final ArrayDeque<Runnable> q=new ArrayDeque<>();public void execute(Runnable r){q.add(r);}void drain(){while(!q.isEmpty())q.remove().run();}}
 static class Store implements DeviceRecoveryCoordinator.Store {PendingDeviceRecoveryStore.Pending value;boolean fail;int writes;long epoch;public long epoch(){return epoch;}public boolean dispatchIfCurrent(long expected,Runnable request){if(expected!=epoch)return false;request.run();return true;}
 public PendingDeviceRecoveryStore.Pending load()throws IOException{check();return value;}
 public PendingDeviceRecoveryStore.Pending prepare(String o,String a,String d,String old)throws IOException{check();writes++;epoch++;return value=pending(false);}
 public PendingDeviceRecoveryStore.Pending markConfirmed(String id)throws IOException{check();assertEquals(ID,id);writes++;epoch++;return value=pending(true);}
 public void acknowledge(String id)throws IOException{check();assertTrue(value.confirmed);assertEquals(ID,id);value=null;writes++;epoch++;}
 public void resetAfterConfirmation(String expected)throws IOException{if(value==null||!value.recoveryId.equals(expected))throw new IOException("STALE");value=null;writes++;epoch++;}void check()throws IOException{if(fail)throw new IOException("FAIL");}}
 static class Request {String path,origin;JSONObject body;AppSessionStore.Session owner;DeviceRecoveryCoordinator.Reply reply;Request(String p,JSONObject b,AppSessionStore.Session o,String origin,DeviceRecoveryCoordinator.Reply r){path=p;body=b;owner=o;this.origin=origin;reply=r;}}
 static class Fixture {final Store store=new Store();final Queue disk=new Queue();final List<Request> requests=new ArrayList<>();final List<String> results=new ArrayList<>();final DeviceRecoveryCoordinator c;int auth;
 Fixture(){c=new DeviceRecoveryCoordinator(store,(m,p,b,o,origin,r)->requests.add(new Request(p,b,o,origin,r)),disk,Runnable::run,new DeviceRecoveryCoordinator.Listener(){public void changed(){}public void sessionAuthenticated(AppSessionStore.Session s){auth++;}});c.updateContext(O,session(A));c.load(results::add);disk.drain();results.clear();}
 void start(){c.start(D,OLD,results::add);disk.drain();}Request last(){return requests.get(requests.size()-1);}void reply(int status,JSONObject b,String code){last().reply.complete(status,b,code);}void success()throws Exception{reply(200,new JSONObject().put("status","recovered").put("device_id",D).put("recovery_id",ID),"");}}
 static JSONObject unauthorized()throws Exception{return new JSONObject().put("code","UNAUTHORIZED");}
 static JSONObject login()throws Exception{return new JSONObject().put("account_id",A).put("session_token","gd_sess_"+"B".repeat(42)+"A");}
 @Test public void checkpointPrecedesHttpAndServerAckPrecedesDurableConfirmation()throws Exception{Fixture f=new Fixture();f.c.start(D,OLD,f.results::add);assertTrue(f.requests.isEmpty());f.disk.drain();assertEquals(OLD,f.last().body.getString("account_token"));assertEquals(NEW,f.last().body.getString("replacement_account_token"));f.success();assertFalse(f.c.requiresAcknowledgement());assertTrue(f.results.isEmpty());f.disk.drain();assertTrue(f.c.requiresAcknowledgement());assertEquals(List.of(""),f.results);}
 @Test public void cancelledPreparationPersistsWithoutHttp(){Fixture f=new Fixture();f.c.start(D,OLD,e->fail());f.c.cancel();f.disk.drain();assertNotNull(f.c.pending());assertTrue(f.requests.isEmpty());}
 @Test public void contextSwitchCancelsOldHttp(){Fixture f=new Fixture();f.c.start(D,OLD,e->fail());f.c.updateContext(O,session("demo-other"));f.disk.drain();assertTrue(f.requests.isEmpty());assertNotNull(f.c.pending());f.c.resume(f.results::add);f.disk.drain();assertEquals(List.of("RECOVERY_CONTEXT_CHANGED"),f.results);}
 @Test public void timeoutPreservesExactRetry(){Fixture f=new Fixture();f.start();String body=f.last().body.toString();f.reply(0,new JSONObject(),"TIMEOUT");f.c.resume(f.results::add);f.disk.drain();assertEquals(body,f.last().body.toString());assertFalse(f.c.pending().confirmed);}
 @Test public void unauthenticatedResumeUsesReplacementFirstThenOldOnlyClean401()throws Exception{Fixture f=new Fixture();f.store.value=pending(false);f.c.load(e->{});f.disk.drain();f.c.updateContext(O,null);f.c.resume(f.results::add);f.disk.drain();assertEquals(NEW,f.last().body.getString("account_token"));f.reply(401,unauthorized(),"");assertEquals(OLD,f.last().body.getString("account_token"));f.reply(201,login(),"");assertEquals(1,f.auth);assertEquals("/v1/devices/"+D+"/recover",f.last().path);f.success();f.disk.drain();assertTrue(f.c.pending().confirmed);}
 @Test public void timeoutOr503NeverFallsBackToOld()throws Exception{for(int status:new int[]{0,503}){Fixture f=new Fixture();f.store.value=pending(false);f.c.load(e->{});f.disk.drain();f.c.updateContext(O,null);f.c.resume(f.results::add);f.disk.drain();f.reply(status,unauthorized(),status==0?"TIMEOUT":"");assertEquals(1,f.requests.size());assertNotNull(f.c.pending());}}
 @Test public void ambiguous401NeverFallsBack()throws Exception{Fixture f=new Fixture();f.store.value=pending(false);f.c.load(e->{});f.disk.drain();f.c.updateContext(O,null);f.c.resume(f.results::add);f.disk.drain();f.reply(401,unauthorized().put("extra",true),"");assertEquals(1,f.requests.size());}
 @Test public void malformedResultNeverConfirms()throws Exception{Fixture f=new Fixture();f.start();f.reply(200,new JSONObject().put("status","recovered").put("device_id","demo-other").put("recovery_id",ID),"");f.disk.drain();assertFalse(f.store.value.confirmed);assertEquals(List.of("RECOVERY_INVALID_RESPONSE"),f.results);}
 @Test public void cancelledServerCallbackDoesNotChangeCheckpoint()throws Exception{Fixture f=new Fixture();f.start();f.c.cancel();f.success();f.disk.drain();assertFalse(f.store.value.confirmed);assertTrue(f.results.isEmpty());}
 @Test public void durableAckCompletesEvenAfterNavigation()throws Exception{Fixture f=new Fixture();f.start();f.success();f.c.cancel();f.disk.drain();assertTrue(f.c.pending().confirmed);assertTrue(f.results.isEmpty());f.c.acknowledge(ID,e->fail());f.c.cancel();f.disk.drain();assertNull(f.c.pending());assertNull(f.store.value);}
 @Test public void failedConfirmationPreservesKey()throws Exception{Fixture f=new Fixture();f.start();f.store.fail=true;f.success();f.disk.drain();assertTrue(f.c.failed());assertNotNull(f.c.pending());assertFalse(f.c.pending().confirmed);}
 @Test public void unconfirmedCannotBeAcknowledged(){Fixture f=new Fixture();f.start();f.reply(0,new JSONObject(),"TIMEOUT");f.c.acknowledge(ID,f.results::add);f.disk.drain();assertNotNull(f.store.value);assertEquals("RECOVERY_ACK_NOT_ALLOWED",f.results.get(1));}
 @Test public void expiredSessionTriesNewLoginAndNeverLoopsAfterSecond401()throws Exception{Fixture f=new Fixture();f.start();f.reply(401,unauthorized(),"");assertEquals(NEW,f.last().body.getString("account_token"));f.reply(201,login(),"");f.reply(401,unauthorized(),"");assertEquals(3,f.requests.size());assertEquals(List.of("RECOVERY_CREDENTIALS_UNRESOLVED"),f.results);assertNotNull(f.c.pending());}
 @Test public void bothLoginCapabilitiesRejectedKeepsCheckpoint()throws Exception{Fixture f=new Fixture();f.start();f.reply(401,unauthorized(),"");f.reply(401,unauthorized(),"");f.reply(401,unauthorized(),"");assertEquals(3,f.requests.size());assertNotNull(f.c.pending());assertEquals(0,f.auth);}
 @Test public void cancelledLoginCannotInstallSession()throws Exception{Fixture f=new Fixture();f.start();f.reply(401,unauthorized(),"");f.c.cancel();f.reply(201,login(),"");assertEquals(0,f.auth);assertEquals(2,f.requests.size());}
 @Test public void wrongAccountLoginNeverInstallsSession()throws Exception{Fixture f=new Fixture();f.start();f.reply(401,unauthorized(),"");f.reply(201,login().put("account_id","demo-wrong"),"");assertEquals(0,f.auth);assertEquals(List.of("RECOVERY_INVALID_RESPONSE"),f.results);}
 @Test public void originSwitchRejectsResumeWithoutRequest(){Fixture f=new Fixture();f.start();f.reply(0,new JSONObject(),"TIMEOUT");int calls=f.requests.size();f.c.updateContext("http://"+"b".repeat(56)+".onion",null);f.c.resume(f.results::add);f.disk.drain();assertEquals(calls,f.requests.size());assertEquals("RECOVERY_CONTEXT_CHANGED",f.results.get(1));}
 @Test public void activityListenerMayEnrichSameSessionWithoutCancellingRecovery()throws Exception{
  Store store=new Store();store.value=pending(false);Queue disk=new Queue(),main=new Queue();List<Request> requests=new ArrayList<>();List<String> result=new ArrayList<>();DeviceRecoveryCoordinator[] ref=new DeviceRecoveryCoordinator[1];
  ref[0]=new DeviceRecoveryCoordinator(store,(m,p,b,o,origin,r)->requests.add(new Request(p,b,o,origin,r)),disk,main,new DeviceRecoveryCoordinator.Listener(){public void changed(){}public void sessionAuthenticated(AppSessionStore.Session s){ref[0].updateContext(O,new AppSessionStore.Session(O,A,"","demo-device-current","gd_dev_"+"A".repeat(43),s.sessionToken));}});
  DeviceRecoveryCoordinator c=ref[0];c.updateContext(O,null);c.load(result::add);disk.drain();assertFalse(c.loaded());main.drain();result.clear();c.resume(result::add);disk.drain();main.drain();requests.get(0).reply.complete(201,login(),"");assertEquals(2,requests.size());assertEquals("demo-device-current",requests.get(1).owner.deviceId);
  requests.get(1).reply.complete(200,new JSONObject().put("status","recovered").put("device_id",D).put("recovery_id",ID),"");disk.drain();assertFalse(c.pending().confirmed);c.cancel();main.drain();assertTrue(c.pending().confirmed);assertTrue(result.isEmpty());
 }
 @Test public void delayedMainPreparationAfterLogoutKeepsCheckpointWithoutHttp(){
  Store store=new Store();Queue disk=new Queue(),main=new Queue();List<Request> requests=new ArrayList<>();DeviceRecoveryCoordinator c=new DeviceRecoveryCoordinator(store,(m,p,b,o,origin,r)->requests.add(new Request(p,b,o,origin,r)),disk,main,new DeviceRecoveryCoordinator.Listener(){public void changed(){}public void sessionAuthenticated(AppSessionStore.Session s){fail();}});
  c.updateContext(O,session(A));c.load(e->{});disk.drain();main.drain();c.start(D,OLD,e->fail());disk.drain();assertNotNull(store.value);assertNull(c.pending());c.updateContext(O,null);main.drain();assertNotNull(c.pending());assertTrue(requests.isEmpty());assertFalse(c.busy());
 }
 @Test public void staleResumeReloadsAndCannotSendDiscardedRequest(){Fixture f=new Fixture();f.start();f.reply(0,new JSONObject(),"TIMEOUT");int calls=f.requests.size();f.store.value=new PendingDeviceRecoveryStore.Pending(O,A,D,"demo-new-request",OLD,NEW,false);f.c.resume(f.results::add);f.disk.drain();assertEquals(calls,f.requests.size());assertEquals("demo-new-request",f.c.pending().recoveryId);assertEquals("RECOVERY_STATE_CHANGED",f.results.get(1));}
 @Test public void queuedMainResumeCannotDispatchAfterAnotherDurableMutation(){
  Store store=new Store();store.value=pending(false);Queue disk=new Queue(),main=new Queue();List<Request> requests=new ArrayList<>();List<String> results=new ArrayList<>();DeviceRecoveryCoordinator c=new DeviceRecoveryCoordinator(store,(m,p,b,o,origin,r)->requests.add(new Request(p,b,o,origin,r)),disk,main,new DeviceRecoveryCoordinator.Listener(){public void changed(){}public void sessionAuthenticated(AppSessionStore.Session s){fail();}});
  c.updateContext(O,null);c.load(e->{});disk.drain();main.drain();c.resume(results::add);disk.drain();store.value=new PendingDeviceRecoveryStore.Pending(O,A,D,"demo-later-recovery",OLD,NEW,false);store.epoch++;main.drain();assertTrue(requests.isEmpty());assertEquals(List.of("RECOVERY_STATE_CHANGED"),results);
 }
 @Test public void authResultCannotDispatchRecoveryAfterCheckpointReplacement()throws Exception{Fixture f=new Fixture();f.start();f.reply(401,unauthorized(),"");f.store.epoch++;f.reply(201,login(),"");assertEquals(2,f.requests.size());assertEquals(List.of("RECOVERY_STATE_CHANGED"),f.results);}
}
